ALTER FILE FORMAT IF EXISTS {{database}}.SOURCE.PARQUET_SNAPPY RENAME TO {{database}}.CORE.PARQUET_SNAPPY;
ALTER FILE FORMAT IF EXISTS {{database}}.METADATA.PROFILE_JSON_FORMAT RENAME TO {{database}}.CORE.PROFILE_JSON_FORMAT;
