-- ---------------------------------------------------------------- references by full name
-- Column defaults that name a sequence
ALTER TABLE {{database}}.CORE.CASE_RECORD ALTER COLUMN CASE_NUMBER SET DEFAULT {{database}}.CORE.CASE_SEQ.NEXTVAL;
ALTER TABLE {{database}}.CORE.INGESTION_CONTROL_CONFIG ALTER COLUMN MASTER_ID SET DEFAULT {{database}}.CORE.SEQ_INGESTION_MASTER_ID.NEXTVAL;
ALTER TABLE {{database}}.CORE.INGESTION_CONTROL_CONFIG ALTER COLUMN CHILD_ID SET DEFAULT {{database}}.CORE.SEQ_INGESTION_CHILD_ID.NEXTVAL;
-- The staged-share landing stage names its file format
ALTER STAGE {{database}}.CORE.LANDING_STAGE SET FILE_FORMAT = (FORMAT_NAME = '{{database}}.CORE.PARQUET_SNAPPY');
-- The case visibility policy reads the domain tables by full name (same rule as V034)
ALTER ROW ACCESS POLICY {{database}}.CORE.DOMAIN_SCOPE SET BODY ->
    ROW_DOMAIN IS NULL
    OR IS_DATABASE_ROLE_IN_SESSION('PLATFORM_ADMIN')
    OR ROW_DOMAIN IN (SELECT DOMAIN_ID FROM {{database}}.CORE.DOMAIN_REGISTRY WHERE UPPER(DOMAIN_NAME) = 'GENERAL')
    OR ROW_DOMAIN IN (SELECT DOMAIN_ID FROM {{database}}.CORE.DOMAIN_MEMBER WHERE UPPER(USER_NAME) = UPPER(CURRENT_USER()))
    OR ROW_DOMAIN NOT IN (SELECT DOMAIN_ID FROM {{database}}.CORE.DOMAIN_MEMBER);
-- The profile alias view selects from its base table by full name
CREATE OR REPLACE VIEW {{database}}.CORE.PERSISTENT_PROFILES COPY GRANTS
  COMMENT = 'Alias of CORE.DATA_PROFILES'
AS SELECT * FROM {{database}}.CORE.DATA_PROFILES;

-- ---------------------------------------------------------------- future grants
-- One schema now holds credential and PII tables as well, so new objects are no longer readable by default:
-- every later migration grants each object it creates (tests/unit/test_platform_schema.py enforces it).
-- Revoking a future grant leaves every grant already made in place.
REVOKE SELECT ON FUTURE TABLES IN SCHEMA {{database}}.CORE FROM DATABASE ROLE {{database}}.VIEWER;
